\begin{definition}
\label{def:3-14-extra-2}



For a finite-dimensional vector space $V$, $a\in V$, and $v\in V$, define
\[
D_v|_a(f)=\left.\frac{d}{dt}\right|_{t=0}f(a+tv),
\qquad f\in C^\infty(V). \tag{3.5}
\]
\end{definition}

